    Record tstatM (cs : list (Z * nat * Z)) (mem : word -> option byte) : Prop := TSM {
      tsm_inv   : mem_inv rsegs mem;
      tsm_stk   : stk rsegs mem slo spm;
      tsm_top   : stk rsegs mem spm (bv_unsigned sp0 - 48);
      tsm_cells : cells_ok mem cs;
      tsm_tid   : exists t, rdn RSEGS mem (Z_to_bv 64 0x10eb50) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 t)) /\ 0 < t < 2 ^ 22;
      tsm_frame : mframe sp0 mem;
      tsm_aux   : exists B', HeapMF_iface.hs_rauxv_ok HM mem B' /\ bv_unsigned sp0 <= B' }.


